const parseFilterInput = (input: string) => {
  const trimmed = input.trim()

  // Поддержка префиксов (кириллица и латиница)
  const projectMatch = trimmed.match(/^(проект|project):(.+)$/i)
  if (projectMatch) {
    return { 
      type: 'project', 
      value: projectMatch[2].trim() 
    }
  }

  // Другие типы фильтров
  const objectMatch = trimmed.match(/^(объект|object):(.+)$/i)
  if (objectMatch) {
    return { type: 'object', value: objectMatch[2].trim() }
  }

  // Обычный текстовый поиск
  return { type: 'text', value: trimmed }
}
